"use client";

import { ReactNode, useRef } from "react";
import OxygenCylinderCalculator from "./oxygen-cylinder-calculator";
import MinuteVentilationCalculator from "./minute-ventilation-calculator";

function DiagnostikSection({ number, kicker, title, children }: { number: string; kicker: string; title: string; children: ReactNode }) {
  return <details className="communication-section qm-section"><summary><span>{number}</span><div><small>{kicker}</small><h2>{title}</h2></div><i>⌄</i></summary><div className="communication-section-content">{children}</div></details>;
}

export default function DiagnostikLesson({ onBack, finale }: { onBack: () => void; finale: ReactNode }) {
  const flowRef = useRef<HTMLDivElement>(null);
  const toggleAll = (open: boolean) => flowRef.current?.querySelectorAll<HTMLDetailsElement>("details").forEach(section => { section.open = open; });
  return <section className="page-section legal-reader communication-reader qm-reader diagnostik-reader">
    <button className="back-button" onClick={onBack}>← Schriftliche Fachbereiche</button>
    <header className="communication-hero qm-hero"><div><span className="eyebrow light">Schriftliche Prüfung · Medizinische Diagnostik</span><h1>Befunde erkennen.<br />Prioritäten sicher setzen.</h1><p>Neurologie, Pädiatrie, EKG, Zugänge, Monitoring, Sauerstoff, Beatmung, Trauma und Reanimation kompakt verbinden.</p></div><div><b>27</b><span>Lernfelder</span><small>NotSan-Prüfung 2027</small></div></header>
    <aside className="communication-focus qm-focus"><span>＋</span><div><b>Prüfungsfokus</b><p>Nicht nur Begriffe aufzählen: Befund erkennen, Aussagegrenzen benennen und daraus die nächste sichere Handlung ableiten.</p></div></aside>
    <div className="communication-toolbar" role="group" aria-label="Leseabschnitte steuern"><button type="button" onClick={() => toggleAll(true)}>Alles ausklappen</button><button type="button" onClick={() => toggleAll(false)}>Alles einklappen</button><small>27 kompakte Lernfelder – klar gegliedert und mobil lesbar.</small></div>
    <div className="communication-reading-flow" ref={flowRef}>
      <DiagnostikSection number="01" kicker="Neurologie" title="Fokal, generalisiert und die Cushing-Trias"><div className="communication-copy"><div className="communication-compare"><article><small>Umschriebener Befund</small><h3>Fokale Ursache</h3><p>Hinweis auf eine bestimmte Hirnregion oder Leitungsbahn: einseitige Parese, Aphasie, Gesichtsfeldausfall oder Blickdeviation. Beispiele sind Schlaganfall, intrakranielle Blutung und fokaler Krampfanfall.</p></article><article><small>Diffuse Hirnfunktionsstörung</small><h3>Generalisierte Ursache</h3><p>Bewusstseinsstörung, symmetrischer Krampfanfall oder globale Verwirrtheit. Mögliche Ursachen: Hypoxie, Hypoglykämie, Intoxikation, metabolische Entgleisung oder generalisierter Anfall.</p></article></div><aside className="communication-case"><small>Cushing-Trias · spätes Warnzeichen</small><p><b>Arterielle Hypertonie</b>, häufig mit verbreiterter Blutdruckamplitude, <b>Bradykardie</b> und <b>veränderte Atmung</b> sprechen für fortgeschrittenen Hirndruck mit drohender Einklemmung. Ein mögliches Beispiel ist die <b>Cheyne-Stokes-Atmung</b> mit periodisch tiefer und flacher werdender Atmung und Atempausen.</p></aside><aside className="communication-exam-tip"><b>Prüfungsfalle</b><p>Ein fokales Muster beweist keinen Schlaganfall und das Fehlen der Cushing-Trias schließt erhöhten Hirndruck nicht aus. cABCDE, Blutzucker, Pupillen, BE-FAST und Verlauf gehören zusammen.</p></aside></div></DiagnostikSection>

      <DiagnostikSection number="02" kicker="Bewusstsein" title="Glasgow Coma Scale · deutsche Variante"><div className="communication-copy"><div className="table-scroll diagnostik-table"><table><thead><tr><th scope="col">Bereich</th><th scope="col">Reaktion</th><th scope="col">Punkte</th></tr></thead><tbody><tr><th rowSpan={4} scope="rowgroup">Augen öffnen (E)</th><td>spontan</td><td>4</td></tr><tr><td>auf Ansprache</td><td>3</td></tr><tr><td>auf Schmerzreiz</td><td>2</td></tr><tr><td>keine Reaktion</td><td>1</td></tr><tr><th rowSpan={5} scope="rowgroup">Verbale Reaktion (V)</th><td>orientiert</td><td>5</td></tr><tr><td>desorientiert / verwirrt</td><td>4</td></tr><tr><td>inadäquate Wörter</td><td>3</td></tr><tr><td>unverständliche Laute</td><td>2</td></tr><tr><td>keine Reaktion</td><td>1</td></tr><tr><th rowSpan={6} scope="rowgroup">Motorische Reaktion (M)</th><td>befolgt Aufforderungen</td><td>6</td></tr><tr><td>gezielte Schmerzabwehr</td><td>5</td></tr><tr><td>ungezielte Schmerzabwehr</td><td>4</td></tr><tr><td>Beugesynergismen</td><td>3</td></tr><tr><td>Strecksynergismen</td><td>2</td></tr><tr><td>keine Reaktion</td><td>1</td></tr></tbody></table></div><aside className="communication-case"><small>Dokumentation</small><p>Einzelwerte, Summe und Verlauf angeben: <b>E2 V3 M5 = GCS 10</b>. Intubation oder nicht prüfbare Komponenten ausdrücklich kennzeichnen, statt einen falschen Zahlenwert zu vergeben.</p></aside><p>Die GCS beschreibt den Reaktionszustand, aber nicht dessen Ursache. Sedierung, Intoxikation, Sprachbarriere, Hypoxie und Hypoglykämie können das Ergebnis beeinflussen.</p></div></DiagnostikSection>

      <DiagnostikSection number="03" kicker="Kardiologie" title="12-Kanal-EKG richtig kleben"><div className="communication-copy"><p>Zehn Elektroden erzeugen zwölf Ableitungen. Die sechs Extremitätenableitungen betrachten das Herz in der Frontalebene, die sechs Brustwandableitungen in der Horizontalebene.</p><aside className="communication-case"><small>Historische Zuordnung · prüfungssicher</small><p><b>Einthoven:</b> bipolare Extremitätenableitungen I, II und III. <b>Goldberger:</b> verstärkte Extremitätenableitungen aVR, aVL und aVF. <b>Wilson:</b> unipolare Brustwandableitungen V1 bis V6. Das heutige 12-Kanal-EKG setzt sich aus allen drei Gruppen zusammen – die sechs Extremitätenableitungen stammen daher nicht allein von Einthoven.</p></aside><h3>IEC-Farben der Elektrodenkabel</h3><div className="ekg-color-grid"><article><small>Extremitäten</small><div className="ekg-color-list"><span><i className="ekg-dot red" /><b>R · Rot</b>rechter Arm</span><span><i className="ekg-dot yellow" /><b>L · Gelb</b>linker Arm</span><span><i className="ekg-dot green" /><b>F · Grün</b>linkes Bein / Fuß</span><span><i className="ekg-dot black" /><b>N · Schwarz</b>rechtes Bein / Neutral</span></div></article><article><small>Brustwand · C entspricht V</small><div className="ekg-color-list"><span><i className="ekg-dot red" /><b>C1/V1 · Rot</b></span><span><i className="ekg-dot yellow" /><b>C2/V2 · Gelb</b></span><span><i className="ekg-dot green" /><b>C3/V3 · Grün</b></span><span><i className="ekg-dot brown" /><b>C4/V4 · Braun</b></span><span><i className="ekg-dot black" /><b>C5/V5 · Schwarz</b></span><span><i className="ekg-dot violet" /><b>C6/V6 · Violett</b></span></div></article></div><div className="table-scroll diagnostik-table ekg-position-table"><table><colgroup><col className="ekg-col-lead" /><col className="ekg-col-position" /><col className="ekg-col-orientation" /></colgroup><thead><tr><th scope="col">Ableitung</th><th scope="col">Exakte Position</th><th scope="col">Orientierung</th></tr></thead><tbody><tr><th scope="row">V1</th><td>4. Interkostalraum rechts parasternal</td><td>rechts neben dem Sternum</td></tr><tr><th scope="row">V2</th><td>4. Interkostalraum links parasternal</td><td>spiegelbildlich zu V1</td></tr><tr><th scope="row">V3</th><td>zwischen V2 und V4</td><td>nach V4 positionieren</td></tr><tr><th scope="row">V4</th><td>5. Interkostalraum links in der Medioklavikularlinie</td><td>zuerst lokalisieren</td></tr><tr><th scope="row">V5</th><td>auf Höhe von V4 in der vorderen Axillarlinie</td><td>horizontal zu V4</td></tr><tr><th scope="row">V6</th><td>auf Höhe von V4/V5 in der mittleren Axillarlinie</td><td>horizontal zu V4/V5</td></tr></tbody></table></div><h3>Fehlerquellen beim Schreiben des EKGs</h3><div className="material-chips"><span>V1/V2 zu hoch geklebt</span><span>V4–V6 nicht horizontal</span><span>V3 vor V4 falsch geschätzt</span><span>Brustwandableitungen auf Brustgewebe</span><span>Extremitätenkabel vertauscht</span><span>Muskelzittern oder Bewegung</span><span>Schlechter Hautkontakt</span><span>Netzstrom- oder Kabelartefakte</span><span>Abweichende Position nicht dokumentiert</span></div></div></DiagnostikSection>

      <DiagnostikSection number="04" kicker="Trauma" title="MILS, STU und Immobilisationsentscheidung"><div className="communication-copy"><div className="communication-compare"><article><small>Manual In-Line Stabilization</small><h3>MILS</h3><p>Eine zweite Person stabilisiert Kopf und Halswirbelsäule manuell in vorgefundener beziehungsweise tolerierter Neutralstellung. Unnötige Flexion, Extension und Rotation werden besonders bei Atemwegsmaßnahmen begrenzt.</p></article><article><small>Schnelle Traumauntersuchung</small><h3>STU</h3><p>Strukturierte Untersuchung von Kopf/Gesicht, Hals, Thorax, Abdomen/Flanken, Becken/Perineum, Extremitäten und Rücken; anschließend pDMS, erneutes cABCDE und Verlauf.</p></article></div><h3>NEXUS-Low-Risk-Kriterien</h3><p>Nach stumpfem Trauma gilt NEXUS nur dann als vollständig negativ, wenn <b>alle fünf</b> Kriterien erfüllt sind:</p><div className="material-chips"><span>Kein Mittelliniendruckschmerz der HWS</span><span>Kein fokal-neurologisches Defizit</span><span>Normale Wachheit</span><span>Kein Hinweis auf Intoxikation</span><span>Keine schmerzhafte ablenkende Verletzung</span></div><aside className="communication-exam-tip"><b>Wichtig</b><p>Sobald ein Kriterium nicht sicher erfüllt ist, ist NEXUS nicht negativ. Die Regel unterstützt die Risikoeinschätzung bei stumpfem Trauma, ersetzt aber weder klinisches Urteil noch lokale Vorgaben und entscheidet nicht allein über jede Form der Bewegungsrestriktion.</p></aside><div className="communication-compare"><article><small>Vollimmobilisation erwägen</small><h3>Hinweise auf Wirbelsäulenverletzung</h3><p>Neurologisches Defizit, Wirbelsäulenschmerz oder Mittelliniendruckschmerz, Deformität, Hochrisikomechanismus oder unzuverlässige Beurteilbarkeit durch Vigilanzminderung, Intoxikation beziehungsweise stark ablenkende Verletzung.</p></article><article><small>Auf starre Zervikalstütze verzichten/abwägen</small><h3>Wenn Schaden überwiegt</h3><p>Keine Indikation nach validierter lokaler Entscheidungsregel; Atemweg oder Ventilation werden behindert; Neutralstellung verstärkt Schmerz oder neurologisches Defizit; starke Agitation; passendes Modell lässt sich nicht korrekt anlegen; bei SHT und Hirndruckverdacht individuelle Abwägung zugunsten alternativer Kopfstabilisierung.</p></article></div><aside className="communication-case"><small>Was bedeutet Vollimmobilisation?</small><p>Bewegungsarme Rettung und Transport auf der Vakuummatratze mit achsengerechter Lagerung und zusätzlicher Kopfstabilisierung. Ein Halskragen allein immobilisiert die Wirbelsäule nicht; ein Spineboard dient vor allem der Rettung und nicht der längeren Transportlagerung.</p></aside><aside className="communication-exam-tip"><b>Sicherheit</b><p>Atemweg und Oxygenierung haben Vorrang. Eine auffällige Kopfstellung wird nicht erzwungen. Auswahl und Verzicht werden anhand Befund, Risiko, Patientenzustand und lokaler Vorgabe begründet und dokumentiert.</p></aside></div></DiagnostikSection>

      <DiagnostikSection number="05" kicker="Gefäßzugang" title="Intraossärer Zugang: VFA, Orte und Nadeln"><div className="communication-copy"><aside className="communication-case"><small>Indikation nach Thüringer VFA 02</small><p>Der intraossäre Zugang ist der alternative Zugangsweg beim <b>akut vital bedrohten Patienten beziehungsweise bei Reanimation</b>, wenn ein i.v.-Zugang nicht innerhalb von <b>60–90 Sekunden</b> etabliert werden kann.</p></aside><div className="communication-compare"><article><small>Punktionsort nach VFA</small><h3>Reihenfolge</h3><p><b>1. proximale Tibia</b>, <b>2. proximaler Humerus</b>. Weitere vom jeweiligen System zugelassene Stellen richten sich nach Geräteeinweisung und lokaler Vorgabe.</p></article><article><small>Ortsbezogene Kontraindikationen</small><h3>An dieser Stelle nicht punktieren</h3><p>Lokale Infektion, massive Weichteilschäden, Fraktur oder Prothese sowie eine vorausgegangene Punktion an derselben Stelle innerhalb der letzten <b>48 Stunden</b>.</p></article></div><h3>EZ-IO-Nadelwahl · Beispiel des verwendeten Systems</h3><div className="table-scroll diagnostik-table"><table><thead><tr><th scope="col">Farbe / Länge</th><th scope="col">Herstellerangabe</th><th scope="col">Typische Einordnung</th></tr></thead><tbody><tr><th scope="row">Rosa · 15 mm</th><td>3–39 kg</td><td>kleine Kinder, meist Tibia</td></tr><tr><th scope="row">Blau · 25 mm</th><td>ab 3 kg</td><td>viele tibiale Zugänge bei durchschnittlichem Weichteilmantel</td></tr><tr><th scope="row">Gelb · 45 mm</th><td>ab 40 kg</td><td>häufig proximaler Humerus beim Erwachsenen oder viel Weichteilgewebe</td></tr></tbody></table></div><aside className="communication-exam-tip"><b>Erfolg prüfen und sicher anwenden</b><p>Punktionsort, Anatomie und Weichteildicke bestimmen die Nadelwahl. Bei Knochenkontakt muss vor dem Bohren mindestens eine schwarze Markierung außerhalb der Haut sichtbar sein. Nach Anlage: sichere Fixierung, leichtgängige Injektion und Blutaspiration prüfen; nach VFA rasch mit NaCl 0,9 % freispülen.</p></aside></div></DiagnostikSection>

      <DiagnostikSection number="06" kicker="Point-of-Care" title="Blutzucker messen und Fehler erkennen"><div className="communication-copy"><h3>Vereinfachte Lernschwellen in beiden Einheiten</h3><div className="table-scroll diagnostik-table glucose-table"><table><thead><tr><th scope="col">Einordnung</th><th scope="col">mg/dl</th><th scope="col">mmol/l</th><th scope="col">Präklinische Bedeutung</th></tr></thead><tbody><tr><th scope="row">Untere Lernschwelle</th><td>≤ 56</td><td>≤ 2,8</td><td>Deutliche Hypoglykämie möglich: Klinik prüfen und nach gültiger VFA behandeln</td></tr><tr><th scope="row">Lern-Orientierungsbereich</th><td>56–176</td><td>2,8–8,8</td><td>Kein diagnostischer Normalbereich; Zeitpunkt, Nahrungsaufnahme und Symptome mitbewerten</td></tr><tr><th scope="row">Obere Lernschwelle</th><td>≥ 176</td><td>≥ 8,8</td><td>Hyperglykämie möglich: Dehydratation, Ketone/Azidose, Vigilanz und Verlauf beachten</td></tr></tbody></table></div><aside className="communication-case"><small>Gewünschte Kopfrechenregel</small><p><b>mg/dl ÷ 20 ≈ mmol/l</b> und <b>mmol/l × 20 ≈ mg/dl</b>. Damit entsprechen 56 mg/dl ungefähr 2,8 mmol/l und 176 mg/dl ungefähr 8,8 mmol/l. Das ist eine grobe Lernregel; die genauere Umrechnung erfolgt mit dem Faktor 18. Therapieentscheidungen richten sich nach Klinik, Messqualität und gültiger VFA.</p></aside><h3>Mess- und Interpretationsfehler</h3><div className="communication-grid"><article><b>Verunreinigte Finger</b><p>Zuckerhaltige Rückstände können falsch hohe Werte erzeugen. Hände reinigen und vollständig trocknen.</p></article><article><b>Nasse Haut / kleine Probe</b><p>Wasser, Desinfektionsmittel oder Gewebsflüssigkeit können verdünnen; Teststreifen vollständig füllen und Vorgaben beachten.</p></article><article><b>Auspressen des Fingers</b><p>Starkes „Melken“ mischt Gewebsflüssigkeit bei und verfälscht die Probe.</p></article><article><b>Schock und Kälte</b><p>Schlechte periphere Perfusion macht kapilläre Messungen unzuverlässiger. Unplausible Werte wiederholen und alternative Probe nach Vorgabe nutzen.</p></article><article><b>Materialfehler</b><p>Abgelaufene, feuchte oder falsch gelagerte Streifen, ungeeignete Temperatur, verschmutztes Gerät oder falsche Codierung/Kalibrierung.</p></article><article><b>Interpretationsfehler</b><p>mg/dl und mmol/l verwechseln, Einzelwert ohne Klinik bewerten oder nach Glukosegabe den Verlauf nicht kontrollieren.</p></article></div><aside className="communication-exam-tip"><b>Merksatz</b><p>Passt der Messwert nicht zur Klinik: Technik und Einheit prüfen, an Hypoperfusion denken, Messung kontrollieren – eine klinisch manifeste Hypoglykämie aber nicht unnötig unbehandelt lassen.</p></aside></div></DiagnostikSection>

      <DiagnostikSection number="07" kicker="Reanimation" title="Effektivität beurteilen und ROSC erkennen"><div className="communication-copy"><h3>Drei technische Hilfsmittel</h3><div className="communication-grid"><article><b>CPR-Feedback</b><p>Defibrillator/Sensor beurteilt Frequenz, Drucktiefe, vollständige Entlastung und Unterbrechungen.</p></article><article><b>Wellenform-Kapnografie</b><p>Überwacht Tubuslage und Ventilation; der Trend gibt indirekte Hinweise auf den erzeugten pulmonalen Blutfluss.</p></article><article><b>Arterielle Druckkurve</b><p>Wenn bereits invasiv vorhanden, liefert sie unmittelbares physiologisches Feedback zur Perfusion unter Kompressionen.</p></article></div><h3>Sauerstoff und SpO₂ richtig einordnen</h3><div className="communication-compare"><article><small>Während der Reanimation</small><h3>Höchstmögliche inspiratorische O₂-Konzentration</h3><p>Während des Kreislaufstillstands wird mit der höchstmöglichen verfügbaren inspiratorischen Sauerstoffkonzentration beatmet. Wegen fehlender oder sehr geringer pulsatiler Perfusion ist die Pulsoxymetrie häufig unzuverlässig und kein Qualitätskriterium für Thoraxkompressionen.</p></article><article><small>Nach ROSC</small><h3>Ziel-SpO₂ 94–98 %</h3><p>Sobald eine zuverlässige Messung möglich ist, wird Sauerstoff auf eine SpO₂ von <b>94–98 %</b> titriert. Hypoxämie und unnötige Hyperoxämie sollen vermieden werden.</p></article></div><h3>Zeichen eines ROSC</h3><div className="material-chips"><span>Zielgerichtete Bewegung/Bewusstsein</span><span>Spontanatmung oder Husten</span><span>Zentraler Puls</span><span>Messbarer Blutdruck</span><span>Pulsatile arterielle Kurve</span><span>Abrupter anhaltender ETCO₂-Anstieg</span></div><aside className="communication-exam-tip"><b>Prüfungsfalle</b><p>Ein organisierter EKG-Rhythmus beweist noch keinen Kreislauf. Auch ein einzelner ETCO₂- oder SpO₂-Wert darf nicht allein zum Unterbrechen oder Beenden der Reanimation führen.</p></aside></div></DiagnostikSection>

      <DiagnostikSection number="08" kicker="Reanimation" title="Reversible Ursachen: 4 H und 4 HITS"><div className="communication-copy"><div className="communication-compare"><article><small>4 H</small><h3>Physiologie wiederherstellen</h3><p><b>Hypoxie:</b> Atemwegsverlegung<br /><b>Hypovolämie:</b> massive Blutung<br /><b>Hypo-/Hyperkaliämie, metabolisch:</b> Dialysepatient mit Hyperkaliämie<br /><b>Hypo-/Hyperthermie:</b> schwere Unterkühlung</p></article><article><small>4 HITS</small><h3>Mechanische oder toxische Ursache</h3><p><b>H · Herzbeuteltamponade:</b> penetrierende Thoraxverletzung<br /><b>I · Intoxikation:</b> Opioidüberdosierung<br /><b>T · Thromboembolie:</b> Herzinfarkt oder massive Lungenarterienembolie<br /><b>S · Spannungspneumothorax:</b> schweres Thoraxtrauma</p></article></div><p>Die Ursachen werden während hochwertiger Thoraxkompressionen anhand von Anamnese, Befund, EKG, Kapnografie und – wenn verfügbar – fokussiertem Ultraschall priorisiert und behandelt.</p></div></DiagnostikSection>

      <DiagnostikSection number="09" kicker="Pharmakologie" title="Applikationswege kurz erklärt"><div className="communication-copy"><div className="table-scroll diagnostik-table"><table><thead><tr><th scope="col">Weg</th><th scope="col">Aufnahme</th><th scope="col">Prüfungsmerkmal</th></tr></thead><tbody><tr><th scope="row">oral (p.o.)</th><td>geschluckt über Magen-Darm-Trakt</td><td>langsamer, variabel; First-Pass-Effekt möglich; nur bei sicherem Schlucken</td></tr><tr><th scope="row">sublingual</th><td>über Schleimhaut unter der Zunge</td><td>rasch, umgeht zunächst Magen-Darm-Trakt und weitgehend den First-Pass-Effekt; nicht sofort schlucken</td></tr><tr><th scope="row">bukkal</th><td>über Wangenschleimhaut</td><td>Schleimhautresorption; Aufnahme kann durch Sekret oder falsche Lage variieren</td></tr><tr><th scope="row">intranasal</th><td>über Nasenschleimhaut</td><td>rasch und nadelfrei; kleine Volumina, Sekret/Blut mindern Aufnahme</td></tr><tr><th scope="row">inhalativ</th><td>über Atemwege und Alveolen</td><td>Wirkung abhängig von Atemtechnik, Ventilation und Partikelablagerung</td></tr><tr><th scope="row">intravenös</th><td>direkt in die Vene</td><td>sofortige systemische Wirkung und vollständige Verfügbarkeit</td></tr><tr><th scope="row">intraossär</th><td>über Markraum in den Kreislauf</td><td>Notfallalternative zum i.v.-Zugang; Medikamente grundsätzlich systemisch wirksam</td></tr><tr><th scope="row">intramuskulär</th><td>in den Muskel</td><td>Resorption perfusionsabhängig; bei Schock verzögert</td></tr><tr><th scope="row">subkutan</th><td>ins Unterhautfettgewebe</td><td>meist langsam; bei Zentralisation unzuverlässiger</td></tr><tr><th scope="row">rektal</th><td>über Rektumschleimhaut</td><td>variable Aufnahme; ein Teil umgeht den First-Pass-Effekt</td></tr><tr><th scope="row">transdermal</th><td>durch die Haut, meist Pflaster</td><td>langsam und lang anhaltend; Depotwirkung nach Entfernen möglich</td></tr></tbody></table></div><aside className="communication-exam-tip"><b>Prüfungsfalle</b><p>Der Applikationsweg verändert Wirkungseintritt und Zuverlässigkeit. „Sublingual“ ist nicht einfach „oral schlucken“, und i.m./s.c. können im Schock deutlich verzögert resorbiert werden.</p></aside></div></DiagnostikSection>

      <DiagnostikSection number="10" kicker="Atemweg" title="Notfallnarkose: Indikation, Zeitpunkt und Komponenten"><div className="communication-copy"><div className="communication-compare"><article><small>Zentrale Indikation 1</small><h3>Atemweg nicht geschützt</h3><p>Fehlende beziehungsweise unmittelbar bedrohte Schutzreflexe oder nicht sicher beherrschbarer Atemweg, etwa bei schwerer Bewusstseinsstörung und Aspirationsgefahr.</p></article><article><small>Zentrale Indikation 2</small><h3>Atmung reicht nicht aus</h3><p>Versagen oder drohendes Versagen von Oxygenierung beziehungsweise Ventilation trotz geeigneter weniger invasiver Maßnahmen, etwa bei Erschöpfung.</p></article></div><aside className="communication-case"><small>Der richtige Zeitpunkt</small><p>Bei klarer Indikation möglichst <b>geplant vor der vollständigen Dekompensation</b>: Teambriefing, Präoxygenierung, Monitoring, Absaugung, Kreislaufvorsorge und Rückfallebene vorbereiten. Schwere Schmerzen, Verletzungsmuster oder unbeherrschbare Agitation können die Gesamtindikation mitbestimmen; starke Schmerzen allein bedeuten zunächst Analgesie, nicht automatisch Narkose.</p></aside><h3>Drei Wirkkomponenten</h3><div className="qm-learning-chain"><span><b>1</b>Analgesie</span><i>＋</i><span><b>2</b>Hypnose</span><i>＋</i><span><b>3</b>neuromuskuläre Blockade</span></div><aside className="communication-exam-tip"><b>Kompetenzgrenze</b><p>Die konkrete Medikamentenwahl und Dosierung richtet sich nach Zustand, Kreislauf, örtlicher Vorgabe, Qualifikation und ärztlicher Entscheidung. Die Notfallnarkose ist ein risikoreicher Teamprozess mit gesicherter Nachbeatmung.</p></aside></div></DiagnostikSection>

      <DiagnostikSection number="11" kicker="Oxygenierung" title="Pulsoxymetrie: SpO₂ verstehen und Grenzen erkennen"><div className="communication-copy"><p>Die Pulsoxymetrie schätzt nichtinvasiv die periphere arterielle Sauerstoffsättigung. Rotes Licht um 660 nm und infrarotes Licht um 940 nm werden von oxygeniertem und desoxygeniertem Hämoglobin unterschiedlich absorbiert; ausgewertet wird der pulsatile arterielle Anteil.</p><div className="communication-grid"><article><b>Messwert plus Signalqualität</b><p>SpO₂, Puls, Plethysmografiekurve und klinischen Puls miteinander vergleichen. Ein Wert ohne plausible Pulswelle ist unsicher.</p></article><article><b>Verzögerter Parameter</b><p>Die Sättigung reagiert zeitverzögert. Unter Sauerstoff kann trotz fehlender Ventilation noch längere Zeit ein guter Wert angezeigt werden.</p></article><article><b>Typische Störungen</b><p>Bewegung, Vasokonstriktion, kalte oder minderperfundierte Extremität, falsche Sensorlage, Nagellack und starkes Fremdlicht.</p></article><article><b>Gefährliche Grenze</b><p>Standard-Pulsoxymeter unterscheiden Oxyhämoglobin nicht sicher von Carboxyhämoglobin. Bei CO-Verdacht kann die SpO₂ trügerisch normal sein.</p></article></div><aside className="communication-exam-tip"><b>Prüfungsfalle</b><p>SpO₂ beurteilt die Oxygenierung, nicht die Ventilation. Eine normale Sättigung schließt Hyperkapnie, Atemerschöpfung oder eine CO-Intoxikation nicht aus. Immer Atemfrequenz, Atemtiefe, Vigilanz, Haut, Auskultation und bei Bedarf Kapnografie zusammenführen.</p></aside></div></DiagnostikSection>

      <DiagnostikSection number="12" kicker="Ventilation" title="Kapnometrie und Kapnografie"><div className="communication-copy"><div className="communication-compare"><article><small>Zahl</small><h3>Kapnometrie</h3><p>Numerische Messung des endtidalen Kohlendioxids, meist als etCO₂ in mmHg. Ein üblicher Orientierungsbereich beträgt etwa <b>35–45 mmHg</b>.</p></article><article><small>Kurve und Zahl</small><h3>Kapnografie</h3><p>Fortlaufende grafische Darstellung des CO₂-Verlaufs über den Atemzyklus. Form, Höhe, Frequenz und Trend liefern mehr Information als ein Einzelwert.</p></article></div><h3>Das normale Kapnogramm</h3><div className="oxygen-phase-grid"><article><b>I · Totraum</b><p>Beginn der Ausatmung, nahezu kein CO₂.</p></article><article><b>II · Anstieg</b><p>Alveolargas mischt sich bei der Exspiration hinzu.</p></article><article><b>III · Plateau</b><p>Überwiegend alveoläres Gas; am Ende wird etCO₂ gemessen.</p></article><article><b>IV · Inspiration</b><p>Steiler Abfall zurück nahe null.</p></article></div><div className="communication-grid"><article><b>etCO₂ steigt</b><p>Zum Beispiel Hypoventilation, gesteigerter Stoffwechsel oder ROSC. Ursache immer im Verlauf und Kontext prüfen.</p></article><article><b>etCO₂ fällt</b><p>Zum Beispiel Hyperventilation, sinkende Lungenperfusion bei Schock/Embolie oder verminderten Stoffwechsel.</p></article><article><b>Plötzlich nahe null</b><p>Diskonnektion, Apnoe, Verlegung, Extubation beziehungsweise ösophageale Lage sofort ausschließen.</p></article><article><b>„Haifischflosse“</b><p>Verlangsamte Exspiration bei Obstruktion, etwa Asthma oder COPD; Klinik und Auskultation bleiben entscheidend.</p></article></div><aside className="communication-case"><small>Reanimation und Atemweg</small><p>Kontinuierliche Wellenform-Kapnografie ist zentral zur Überwachung einer endotrachealen Tubuslage und zur Trendbeurteilung unter CPR. Ein abrupter, anhaltender etCO₂-Anstieg kann auf ROSC hinweisen.</p></aside><aside className="communication-exam-tip"><b>Aussagegrenze</b><p>etCO₂ hängt von Ventilation, Stoffwechsel und pulmonaler Durchblutung ab. Ein veränderter Wert beweist deshalb allein weder Hyperventilation noch Lungenembolie; Kurve, Technik, Kreislauf und Patient müssen gemeinsam beurteilt werden.</p></aside></div></DiagnostikSection>

      <DiagnostikSection number="13" kicker="Therapie und Berechnung" title="Sauerstoffgabe und Flaschenlaufzeit"><div className="communication-copy"><p>Sauerstoff ist ein Medikament: Indikation, Zielbereich, Applikationssystem, Fluss, Wirkung und Verlauf werden festgelegt und dokumentiert. Bei akuter Hypoxämie wird die Gabe an Klinik und Ziel-SpO₂ titriert; bei Risiko einer hyperkapnischen respiratorischen Insuffizienz ist eine kontrollierte Gabe mit engmaschiger Reevaluation besonders wichtig.</p><div className="communication-grid"><article><b>Nasenbrille</b><p>Für niedrige bis mittlere Flüsse bei spontan atmenden, kooperativen Patienten; tatsächliche Sauerstoffkonzentration hängt von Atemmuster und Mundatmung ab.</p></article><article><b>Sauerstoffmaske</b><p>Fluss passend zum verwendeten Maskensystem einstellen. Zu niedriger Fluss kann bei einfachen Masken die CO₂-Rückatmung begünstigen.</p></article><article><b>Reservoirmaske</b><p>Für hohe inspiratorische Sauerstoffkonzentration; Reservoir vorfüllen und während der Inspiration ausreichend gefüllt halten.</p></article><article><b>Beatmung</b><p>Bei unzureichender Ventilation reicht Sauerstoff allein nicht: Atemweg öffnen und mit geeignetem System wirksam ventilieren; Kapnografie nutzen.</p></article></div><h3>Sicherer Umgang mit medizinischem Sauerstoff</h3><div className="oxygen-safety-grid"><article><span>01</span><b>Flasche sichern</b><p>Druckgasflaschen gegen Umfallen, Herabfallen und unkontrollierte Bewegung sichern – im Fahrzeug, beim Transport und am Einsatzort. Vor Hitze und mechanischer Beschädigung schützen.</p></article><article><span>02</span><b>Brandlast vermeiden</b><p>Sauerstoff fördert Verbrennungen. Kein Rauchen, keine offene Flamme oder Funkenquelle; sauerstoffangereicherte Kleidung und Umgebung beachten.</p></article><article><span>03</span><b>Öl- und fettfrei</b><p>Ventile, Druckminderer, Anschlüsse und Hände müssen frei von Öl, Fett und fetthaltiger Pflege sein. Nur für Sauerstoff zugelassene Armaturen verwenden.</p></article><article><span>04</span><b>Langsam öffnen</b><p>Flaschenventil kontrolliert und langsam von Hand öffnen. Nicht mit Werkzeug erzwingen; beschädigte, schwergängige oder undichte Systeme außer Betrieb nehmen.</p></article><article><span>05</span><b>Vor Einsatz prüfen</b><p>Flaschendruck, Dichtung, Druckminderer, Schlauch, Applikationssystem und Dichtheit prüfen. Restmenge mit Reserve und Transportzeit berechnen.</p></article><article><span>06</span><b>Nach Gebrauch</b><p>Fluss beenden, Flaschenventil schließen, System nach Gerätevorgabe druckentlasten und Material wieder sicher lagern. Verbrauch und verbleibenden Vorrat kontrollieren.</p></article></div><aside className="communication-exam-tip"><b>Medizin und Technik zusammen denken</b><p>Sauerstoff ersetzt keine Ventilation. Patient, Atemarbeit, SpO₂, Vigilanz und gegebenenfalls etCO₂ werden wiederholt beurteilt; gleichzeitig müssen Flasche, Armaturen und Reichweite sicher beherrscht werden.</p></aside><OxygenCylinderCalculator /></div></DiagnostikSection>

      <DiagnostikSection number="14" kicker="Thoraxnotfall" title="Entlastungspunktion: Indikation, Differenzialdiagnosen und Orte"><div className="communication-copy"><aside className="communication-case"><small>Indikation nach Thüringer VFA 07</small><p><b>Thoraxtrauma</b> mit <b>mindestens einseitig abgeschwächtem Atemgeräusch</b> und <b>hämodynamischer Instabilität</b>. Die drei Bestandteile gehören zusammen; ein einfacher stabiler Pneumothorax erfüllt diese Entlastungsindikation nicht.</p></aside><div className="communication-compare"><article><small>Monaldi-Zugang</small><h3>2. ICR · Medioklavikularlinie</h3><p>Interkostalraum sicher identifizieren. Die Punktion erfolgt im 90-Grad-Winkel zur Thoraxwand unmittelbar über dem Oberrand der unteren Rippe.</p></article><article><small>Bülau-Zugang</small><h3>4./5. ICR · vordere Axillarlinie</h3><p>Zweiter Punktionsort nach VFA, ebenfalls senkrecht zur Thoraxwand und über dem Rippenoberrand. Die VFA verlangt eine geeignete Thoraxpunktionskanüle von mindestens 6,5 cm.</p></article></div><aside className="communication-case"><small>Warum über den Rippenoberrand?</small><p>Das größere Interkostalgefäß-Nerven-Bündel aus <b>Vene, Arterie und Nerv</b> verläuft geschützt im Sulcus costae am Unterrand der jeweils darüberliegenden Rippe. Deshalb wird unmittelbar <b>über dem Oberrand der unteren Rippe</b> punktiert, um Verletzungen und Blutungen möglichst zu vermeiden. Kleine Kollateraläste können dennoch vorkommen – Anatomie und saubere Punktion bleiben entscheidend.</p></aside><h3>Wichtige Differenzialdiagnosen und Ursachen fehlender Besserung</h3><div className="material-chips"><span>Tubusfehllage oder einseitige Intubation</span><span>Hämatothorax</span><span>Lungenarterienembolie</span><span>Akutes Koronarsyndrom</span><span>Aortendissektion</span><span>Asthma-/COPD-Exazerbation</span><span>Atelektase oder Sekretverlegung</span><span>Herzbeuteltamponade</span></div><aside className="communication-exam-tip"><b>Nach der Punktion</b><p>Nach Luftentweichen Stahlmandrin entfernen, Kanüle fixieren und die <b>respiratorische sowie hämodynamische Wirkung</b> erneut beurteilen. Fehlende Stabilisierung beweist nicht automatisch einen falschen Punktionsort – Patient, Beatmung, Kanüle und Differenzialdiagnosen müssen systematisch geprüft werden.</p></aside></div></DiagnostikSection>

      <DiagnostikSection number="15" kicker="Arbeitsschutz" title="Vorgehen bei Nadelstichverletzung"><div className="communication-copy"><aside className="communication-focus qm-focus"><span>!</span><div><b>Nicht bagatellisieren</b><p>Eine Verletzung mit möglicherweise kontaminierter Kanüle ist ein Arbeitsunfall. Versorgung, Meldung und Risikobewertung beginnen sofort – die Arbeit wird nicht einfach fortgesetzt.</p></div></aside><div className="needle-stick-flow"><article><span>01</span><div><b>Sofort versorgen</b><p>Wunde nicht auspressen oder aggressiv manipulieren. Spontanen Blutfluss kurz zulassen beziehungsweise fördern und anschließend gründlich desinfizieren. Auge oder Schleimhaut sofort ausgiebig mit Wasser oder NaCl 0,9 % spülen.</p></div></article><article><span>02</span><div><b>Unfall melden</b><p>Vorgesetzte oder festgelegte Meldestelle sofort informieren. Zeitpunkt, Instrument, Verletzungstiefe, Kontamination und getragene Schutzmaßnahmen dokumentieren.</p></div></article><article><span>03</span><div><b>Ärztlich vorstellen</b><p>Unverzüglich Betriebsarzt, D-Arzt oder festgelegte Notfallambulanz aufsuchen. Impfausweis beziehungsweise Hepatitis-B-Impfstatus mitnehmen.</p></div></article><article><span>04</span><div><b>Risiko bewerten</b><p>HBV-, HCV- und HIV-Risiko anhand der Exposition beurteilen, Basisserologie abnehmen und Nachkontrollen festlegen. Bluttests der Indexperson benötigen deren Einwilligung.</p></div></article><article><span>05</span><div><b>Postexposition handeln</b><p>HIV-PEP bei relevanter Exposition sofort ärztlich prüfen und, wenn indiziert, möglichst innerhalb der ersten Stunden beginnen. Hepatitis-B-Schutz ergänzen; gegen HCV gibt es keine Impfung oder PEP.</p></div></article></div><aside className="communication-exam-tip"><b>Prüfungsmerksatz</b><p><b>Versorgen – melden – ärztlich bewerten – dokumentieren – Nachsorge sichern.</b> Zusätzlich gelten Hygieneplan, Betriebsanweisung und die Vorgaben des zuständigen Unfallversicherungsträgers.</p></aside></div></DiagnostikSection>

      <DiagnostikSection number="16" kicker="Wissenschaftliches Arbeiten" title="Quellen prüfen, Methoden verstehen, Aussagen bewerten"><div className="communication-copy"><p>Wissenschaftliches Arbeiten bedeutet, eine klare Frage mit nachvollziehbaren Methoden, geeigneten Quellen und logisch begründeten Schlussfolgerungen zu bearbeiten. Für die Prüfung ist entscheidend, <b>wie belastbar eine Aussage ist</b> – nicht nur, ob sie überzeugend klingt.</p><h3>Drei klassische Gütekriterien</h3><div className="science-quality-grid"><article><span>O</span><b>Objektivität</b><p>Das Ergebnis ist möglichst unabhängig davon, wer Untersuchung, Auswertung oder Interpretation durchführt. Standardisierte Abläufe erhöhen die Objektivität.</p></article><article><span>R</span><b>Reliabilität</b><p>Eine Messung liefert unter gleichen Bedingungen zuverlässig vergleichbare Ergebnisse. Reliabilität beschreibt die Messgenauigkeit.</p></article><article><span>V</span><b>Validität</b><p>Die Methode misst tatsächlich das Merkmal, das sie messen soll. Ein Verfahren kann zuverlässig sein und trotzdem das falsche Merkmal erfassen.</p></article></div><h3>Weitere Qualitätsanforderungen</h3><div className="science-standards"><span><b>Relevanz</b>Die Information beantwortet die konkrete Fragestellung.</span><span><b>Logik</b>Argumente und Schlussfolgerungen sind widerspruchsfrei und nachvollziehbar.</span><span><b>Prägnanz</b>Die Kernaussage ist klar, genau und ohne unnötige Umwege formuliert.</span></div><h3>Literatur und Bilder systematisch bewerten</h3><div className="communication-grid"><article><b>Primärquelle bevorzugen</b><p>Sie berichtet die ursprüngliche Untersuchung, Originaldaten oder eine Originalleitlinie. Sekundärquellen ordnen Wissen ein, sollten aber zur Primärquelle zurückverfolgt werden.</p></article><article><b>Herkunft und Aktualität</b><p>Autorenschaft, Institution, Erscheinungsdatum, Fachgebiet, Interessenkonflikte und Aktualität prüfen. Bekanntheit allein beweist keine Qualität.</p></article><article><b>Methoden prüfen</b><p>Fragestellung, Studiendesign, Stichprobe, Vergleichsgruppe, Messverfahren, Auswertung, Ausfälle und mögliche Verzerrungen beurteilen.</p></article><article><b>Quellen vergleichen</b><p>Mehrere hochwertige Quellen gegenüberstellen: Stimmen Population, Endpunkte und Methoden überein? Abweichungen erklären statt Mehrheitsmeinungen einfach zu zählen.</p></article><article><b>Bilder kritisch prüfen</b><p>Originalquelle, Urheber, Lizenz, Datum und Kontext klären. Auf Bearbeitung, falsche Beschriftung, fehlenden Maßstab und ausreichende Auflösung achten.</p></article><article><b>Übertragbarkeit begrenzen</b><p>Prüfen, ob Ergebnisse zur eigenen Fragestellung, Patientengruppe und zum präklinischen Kontext passen. Unsicherheiten und Grenzen offen benennen.</p></article></div><h3>Drei methodische Denkwege</h3><div className="science-method-grid"><article><small>Allgemein → Einzelfall</small><b>Deduktiv</b><p>Aus einer allgemeinen Regel wird eine konkrete Erwartung abgeleitet. Beispiel: Hypoventilation erhöht typischerweise CO₂; daher wird bei flacher Atmung ein steigendes etCO₂ erwartet – der Messbefund muss die Annahme trotzdem bestätigen.</p></article><article><small>Beobachtung → allgemeine Annahme</small><b>Induktiv</b><p>Aus mehreren Einzelbeobachtungen wird eine vorläufige allgemeine Aussage entwickelt. Sie bleibt überprüfbar und darf nicht vorschnell verallgemeinert werden.</p></article><article><small>Definierte Kriterien → Unterschiede</small><b>Vergleichend</b><p>Quellen, Gruppen oder Verfahren werden anhand vorher festgelegter Kriterien gegenübergestellt, zum Beispiel Aussagekraft, Risiken, Stichprobe und Übertragbarkeit.</p></article></div><aside className="communication-case"><small>Prüfungsschema in fünf Schritten</small><p><b>Fragestellung klären → Originalquelle suchen → Methode prüfen → Qualität und Übertragbarkeit bewerten → Ergebnis mit Grenzen formulieren.</b></p></aside><aside className="communication-exam-tip"><b>Prüfungsfalle</b><p>Reliabilität ist nicht automatisch Validität: Eine Waage, die immer zwei Kilogramm zu viel anzeigt, misst sehr zuverlässig, aber nicht richtig. Auch eine aktuelle oder professionell gestaltete Quelle ist nicht automatisch belastbar.</p></aside></div></DiagnostikSection>
      <DiagnostikSection number="17" kicker="Nicht-invasive Atemunterstützung" title="CPAP, PEEP und ASB sicher unterscheiden"><div className="communication-copy"><p>CPAP/ASB unterstützt einen <b>spontan atmenden, ausreichend wachen und kooperativen Patienten</b> über eine dicht sitzende Maske. Es ist keine „Sauerstoffmaske mit mehr Druck“, sondern eine überwachte nicht-invasive Beatmung mit klarer Indikation, Kontraindikationsprüfung und jederzeit verfügbarer Eskalationsmöglichkeit.</p><div className="niv-pressure-model"><article><span>Grundniveau</span><b>CPAP / PEEP</b><p><strong>CPAP</strong> hält während Ein- und Ausatmung ein kontinuierlich positives Atemwegsdruckniveau. Der dabei am Ende der Ausatmung verbleibende positive Druck heißt <strong>PEEP</strong>. Er kann kollabierte, noch rekrutierbare Alveolen offenhalten, die funktionelle Residualkapazität erhöhen und beim kardialen Lungenödem Vor- und Nachlast vermindern.</p></article><i>＋</i><article><span>Inspirationshilfe</span><b>ASB / P<sub>ASB</sub></b><p><strong>ASB</strong> gibt auf jeden vom Patienten ausgelösten Atemzug zusätzlichen inspiratorischen Druck. Dadurch sinken Atemarbeit und Belastung der Atemmuskulatur; Atemzugvolumen und Ventilation können zunehmen. Ohne eigene Triggerung ersetzt ASB keine kontrollierte Beatmung.</p></article></div><h3>Druckverhältnis verstehen</h3><div className="niv-equation"><span><small>Exspiration</small><b>PEEP 5 mbar</b></span><i>＋</i><span><small>zusätzliche Inspiration</small><b>ASB 5 mbar</b></span><i>＝</i><span className="result"><small>inspiratorischer Spitzendruck</small><b>etwa 10 mbar</b></span></div><p>Der wirksame Unterstützungsdruck ist die <b>Differenz zwischen inspiratorischem Druck und PEEP</b>. Geräte können P<sub>ASB</sub> entweder als zusätzliche Druckunterstützung oder als absoluten inspiratorischen Zielwert darstellen – deshalb Anzeige, Geräteeinweisung und lokale VFA prüfen.</p><div className="communication-compare"><article><small>Erwünschte Wirkung</small><h3>Oxygenierung und Atemarbeit</h3><p>Alveolen offenhalten, funktionelle Residualkapazität erhöhen, Atemmuskulatur entlasten und bei passender Obstruktion den inspiratorischen Aufwand gegen intrinsischen PEEP vermindern. Wirkung an Atemfrequenz, Atemarbeit, SpO₂, etCO₂, Vigilanz und subjektiver Dyspnoe prüfen.</p></article><article><small>Risiken</small><h3>Druck ist Kreislauf- und Lungentherapie</h3><p>Zu hoher Druck kann venösen Rückstrom und Blutdruck senken, Leckagen, Mageninsufflation und Barotrauma begünstigen. Bei Obstruktion kann eine zu kurze Exspirationszeit Air-Trapping und dynamische Überblähung verstärken.</p></article></div><h3>Grenzen und Therapieversagen</h3><div className="material-chips"><span>Fehlende Schutzreflexe</span><span>Bewusstlosigkeit oder sinkende Vigilanz</span><span>Aktives Erbrechen / hohe Aspirationsgefahr</span><span>Fehlende Kooperation</span><span>Ungeeignete Gesichtsverletzung / undichte Maske</span><span>Apnoe oder unzureichende Eigenatmung</span><span>Unbeherrschbare Sekrete</span><span>Kreislaufverschlechterung</span></div><aside className="communication-exam-tip"><b>Prüfungsfalle</b><p>Eine steigende SpO₂ allein beweist keinen Erfolg. Sinkende Vigilanz, unregelmäßige oder flacher werdende Atmung, „silent chest“, zunehmendes etCO₂ oder Kreislaufabfall sprechen für drohendes Therapieversagen. CPAP/ASB darf eine notwendige Atemwegssicherung und kontrollierte Beatmung nicht verzögern.</p></aside></div></DiagnostikSection>
      <DiagnostikSection number="18" kicker="Kontrollierte Beatmung" title="Volumen-, Druckkontrolle und AMV"><div className="communication-copy"><div className="communication-compare"><article><small>Volumenkontrolliert</small><h3>Volumen ist eingestellt</h3><p>Atemzugvolumen und Frequenz werden vorgegeben. Der notwendige Beatmungsdruck ist das Ergebnis und steigt beispielsweise bei sinkender Compliance, erhöhtem Atemwegswiderstand oder Tubusproblem. Druckgrenzen und exspiratorisches Volumen überwachen.</p></article><article><small>Druckkontrolliert</small><h3>Druck ist eingestellt</h3><p>Inspiratorischer Druck, PEEP und Frequenz werden vorgegeben. Das erreichte Atemzugvolumen ist das Ergebnis und kann bei veränderter Compliance, Resistance oder Leckage fallen. Exspiratorisches VT und AMV engmaschig kontrollieren.</p></article></div><h3>Atemminutenvolumen berechnen</h3><p><b>AMV [l/min] = Atemzugvolumen [ml] × Atemfrequenz [/min] ÷ 1000.</b> Beispiel: 500 ml × 12/min = 6 l/min.</p><MinuteVentilationCalculator /><aside className="communication-exam-tip"><b>Prüfungsfalle</b><p>Gleiches AMV bedeutet nicht automatisch gleiche alveoläre Ventilation. Bei kleinen, schnellen Atemzügen nimmt der Totraumanteil relativ zu; deshalb etCO₂ beziehungsweise BGA, Thoraxexkursion, Auskultation, SpO₂, Drücke und klinischen Verlauf zusammen beurteilen.</p></aside></div></DiagnostikSection>
      <DiagnostikSection number="19" kicker="Todesfeststellung" title="Sichere und unsichere Todeszeichen"><div className="communication-copy"><p>Unsichere Todeszeichen zeigen einen möglichen Kreislaufstillstand, beweisen den irreversiblen Tod aber nicht. Fehlen sichere Todeszeichen, wird bei entsprechender Indikation unverzüglich reanimiert und parallel nach reversiblen Ursachen gesucht.</p><div className="communication-compare"><article><small>Reanimation prüfen oder beginnen</small><h3>Unsichere Todeszeichen</h3><p>Bewusstlosigkeit, fehlende normale Atmung, fehlender zentraler Puls beziehungsweise keine sicheren Kreislaufzeichen, fehlende Reflexe, lichtstarre Pupillen, Blässe, Zyanose und Abkühlung.</p></article><article><small>Tod sicher eingetreten</small><h3>Sichere Todeszeichen</h3><p>Totenflecken (Livores), Totenstarre (Rigor mortis), Fäulnis beziehungsweise Verwesung und mit dem Leben unvereinbare Verletzungen.</p></article></div><aside className="communication-exam-tip"><b>Prüfungsfalle</b><p>Asystolie, fehlende Pupillenreaktion oder Unterkühlung sind für sich allein keine sicheren Todeszeichen. Hirntod ist ebenfalls keine präklinische Blickdiagnose, sondern wird nach einem festgelegten ärztlichen Verfahren festgestellt.</p></aside><aside className="communication-case"><small>Präklinische Konsequenz</small><p>Bei sicheren Todeszeichen wird keine Reanimation begonnen. Befund, Umstände, Eigenschutz, Polizei- beziehungsweise Notarztnachforderung und weiteres Vorgehen richten sich nach Lage und lokalen Vorgaben; die ärztliche Leichenschau wird dadurch nicht ersetzt.</p></aside></div></DiagnostikSection>
      <DiagnostikSection number="20" kicker="Gefahrenrettung" title="Rautek-Rettungsgriff: Anwendung und Risiken"><div className="communication-copy"><aside className="communication-case"><small>Beispiel</small><p>Ein bewusstloser Patient liegt in einem verrauchten Fahrzeug und kann dort nicht sicher untersucht oder reanimiert werden. Nach Eigenschutz und schnellstmöglicher Gefahrenbeseitigung wird er mit dem Rautek-Rettungsgriff auf eine sichere Fläche gebracht; dort beginnen sofort cABCDE und erforderliche Reanimation.</p></aside><h3>So wird der Griff grundsätzlich durchgeführt</h3><div className="legal-checklist"><span>Patienten von hinten unter den Achseln fassen</span><span>Einen Unterarm des Patienten quer vor den Brustkorb legen</span><span>Unterarm mit Affengriff an Handgelenk und Ellenbogennähe sichern</span><span>Patienten körpernah anheben oder zurückziehen</span><span>Nur bis zur sicheren Versorgungsfläche retten</span><span>Anschließend sofort neu beurteilen</span></div><aside className="communication-exam-tip"><b>Warum ist Vorsicht geboten?</b><p>Der Griff bewegt Wirbelsäule, Schultergürtel und verletzte Extremitäten und kann Schmerzen oder bestehende Verletzungen verschlimmern. Er ist daher eine <b>Gefahrenrettung</b>, keine bequeme Standard-Umlagerung. Ohne unmittelbare Gefahr werden schonendere Hilfsmittel und achsengerechte Techniken bevorzugt; Lebensrettung und Eigenschutz haben im echten Gefahrenbereich Vorrang.</p></aside></div></DiagnostikSection>
      <DiagnostikSection number="21" kicker="Kreislauf" title="Normotension, Hypertonie und Hypotonie im Fall einordnen"><div className="communication-copy"><div className="table-scroll diagnostik-table"><table><thead><tr><th scope="col">Einordnung</th><th scope="col">Orientierung beim Erwachsenen</th><th scope="col">Rettungsdienstliche Bedeutung</th></tr></thead><tbody><tr><th scope="row">Normotension</th><td>Blutdruck im erwartbaren individuellen Bereich, ohne Zeichen der Minderperfusion</td><td>Schließt eine kompensierte oder verborgene Blutung nicht aus</td></tr><tr><th scope="row">Hypertonie</th><td>Wiederholt mindestens etwa 140/90 mmHg; Akutwert im Kontext bewerten</td><td>Kann chronisch, schmerz-/stressbedingt oder Ausdruck eines Notfalls mit Organschaden sein</td></tr><tr><th scope="row">Hypotonie</th><td>Häufig systolisch unter 90 mmHg oder deutlicher Abfall vom Ausgangswert</td><td>Mit kalter Haut, Vigilanzstörung, schwachem Puls oder verlängerter Rekapillarisierung Hinweis auf Minderperfusion</td></tr></tbody></table></div><h3>Typische Prüfungsfälle</h3><div className="communication-grid"><article><b>Blutung · noch hämodynamisch stabil</b><p>Der Blutdruck kann zunächst normotensiv bleiben, weil Tachykardie und Vasokonstriktion kompensieren. Blutungsquelle, Haut, Puls, Rekapillarisierung, Bewusstsein und Verlauf wiederholt prüfen.</p></article><article><b>Blutung · hämodynamisch instabil</b><p>Hypotonie ist häufig ein spätes Dekompensationszeichen. Kaltschweißigkeit, Unruhe oder Bewusstseinsstörung, schwacher schneller Puls und zunehmende Kreislaufverschlechterung machen die Blutung zeitkritisch.</p></article><article><b>SHT · Cushing-Trias</b><p>Bei fortgeschrittenem Hirndruck können arterielle Hypertonie mit verbreiterter Blutdruckamplitude, Bradykardie und veränderte Atmung auftreten. Das ist kein Zeichen hämodynamischer Entwarnung, sondern ein spätes neurologisches Warnsignal.</p></article><article><b>SHT plus Blutung</b><p>Gegenläufige Mechanismen können das typische Bild abschwächen. Deshalb keine Diagnose aus einem Einzelwert ableiten: Blutungs- und Hirndruckzeichen parallel suchen und seriell beurteilen.</p></article></div><aside className="communication-exam-tip"><b>Merksatz</b><p><b>Hämodynamisch stabil</b> bedeutet ausreichende Organperfusion ohne fortschreitende Kreislaufdekompensation – nicht lediglich „Blutdruck noch normal“.</p></aside></div></DiagnostikSection>
      <DiagnostikSection number="22" kicker="Schmerzdiagnostik" title="Pain Assessment in sieben Punkten"><div className="communication-copy"><p>Das Schmerzassessment verbindet <b>OPQRST</b> mit relevanten Begleitsymptomen. Es wird vor und nach einer Maßnahme wiederholt und zusammen mit Vitalzeichen und klinischem Befund dokumentiert.</p><ol className="listening-steps"><li><b>O · Onset</b><span>Wann und wie begann der Schmerz – plötzlich oder schleichend?</span></li><li><b>P · Provocation/Palliation</b><span>Was verstärkt oder lindert ihn, etwa Bewegung, Atmung, Druck oder Ruhe?</span></li><li><b>Q · Quality</b><span>Wie fühlt er sich an: drückend, stechend, brennend, kolikartig oder reißend?</span></li><li><b>R · Region/Radiation</b><span>Wo sitzt der Schmerz und wohin strahlt er aus?</span></li><li><b>S · Severity</b><span>Stärke auf NRS 0–10; bei ungeeigneter Selbstauskunft passende Beobachtungsskala nutzen.</span></li><li><b>T · Time</b><span>Dauer, Verlauf, Dynamik, Episoden und frühere vergleichbare Beschwerden.</span></li><li><b>A · Associated symptoms</b><span>Begleitsymptome wie Dyspnoe, Übelkeit, Kaltschweißigkeit, Synkope oder neurologische Ausfälle.</span></li></ol><aside className="communication-case"><small>Dokumentation</small><p>Nicht nur „Schmerz 8/10“ notieren: Lokalisation, Qualität, Beginn, Verlauf, Begleitsymptome sowie Wirkung und Nebenwirkungen der Behandlung gehören dazu.</p></aside></div></DiagnostikSection>
      <DiagnostikSection number="23" kicker="Rettungsdienstsystem" title="Ärztliche Leitung Rettungsdienst: zwei Kernaufgaben"><div className="communication-copy"><div className="communication-compare"><article><small>1 · Medizinische Systemverantwortung</small><h3>Standards festlegen</h3><p>Die Ärztliche Leitung Rettungsdienst entwickelt beziehungsweise verantwortet medizinische Vorgaben, Behandlungsstandards und Qualitätssicherungsmaßnahmen für das Rettungsdienstsystem.</p></article><article><small>2 · Qualität überprüfen</small><h3>Anwendung auswerten</h3><p>Sie überprüft Versorgungsqualität und Anwendung der Vorgaben, wertet relevante Daten und Ereignisse aus und leitet Fortbildung oder Verbesserungsmaßnahmen ab.</p></article></div><aside className="communication-exam-tip"><b>Nicht verwechseln</b><p>Die Ärztliche Leitung Rettungsdienst führt das medizinische System. Sie ist nicht automatisch der behandelnde Notarzt eines konkreten Einsatzes und nicht mit dem Leitenden Notarzt einer Großschadenslage gleichzusetzen.</p></aside></div></DiagnostikSection>
      <DiagnostikSection number="24" kicker="Sekundärtransport" title="ITW: Checkliste vor dem Intensivtransport"><div className="communication-copy"><p>Ein Intensivtransport darf laufende intensivmedizinische Therapie und Überwachung nicht unkontrolliert unterbrechen. Die Vorbereitung erfolgt gemeinsam im Transportteam und endet mit einem Team-Time-out.</p><div className="needle-stick-flow"><article><span>01</span><div><b>Auftrag und Ziel</b><p>Indikation, Dringlichkeit, Zielklinik, Aufnahmebestätigung, Ansprechpartner, Strecke und voraussichtliche Dauer klären.</p></div></article><article><span>02</span><div><b>Arzt-Arzt-Gespräch</b><p>Diagnosen, Verlauf, aktuelle Probleme, Therapieziele, Risiken und notwendige Maßnahmen vor Transportbeginn übergeben.</p></div></article><article><span>03</span><div><b>Transportfähigkeit</b><p>cABCDE, Kreislauf, Oxygenierung, Ventilation, Temperatur, Analgosedierung und Lagerung stabilisieren; vermeidbare Interventionen vor Abfahrt durchführen.</p></div></article><article><span>04</span><div><b>Atemweg und Beatmung</b><p>Tubus beziehungsweise Trachealkanüle sichern, Transportbeatmung testen, Einstellungen übernehmen, Kapnografie und ausreichende Sauerstoffreserve berechnen.</p></div></article><article><span>05</span><div><b>Monitoring</b><p>EKG, SpO₂, Blutdruck und etCO₂ fortführen; erforderliche invasive Messungen, Alarmgrenzen und Signalqualität prüfen.</p></div></article><article><span>06</span><div><b>Zugänge und Drainagen</b><p>Alle Zugänge, arterielle Leitungen, Thoraxdrainagen, Katheter und Sonden sichern, beschriften und auf Funktion, Füllstand sowie ausreichende Schlaufenlänge prüfen.</p></div></article><article><span>07</span><div><b>Medikamente und Pumpen</b><p>Wirkstoff, Konzentration, Rate, Restlaufzeit, Kompatibilität und Reserve kontrollieren; Pumpen, Kabel und Akkus transportfest sichern.</p></div></article><article><span>08</span><div><b>Notfallreserve</b><p>Beatmungsbeutel, Absaugung, Atemwegsmaterial, Defibrillation, Notfallmedikamente und Ersatzmaterial unmittelbar erreichbar halten.</p></div></article><article><span>09</span><div><b>Dokumente und Besonderheiten</b><p>Arztbrief, Befunde, Bilder, Labor, Medikationsplan, Einwilligung, Allergien, Isolation und besondere Geräte vollständig übernehmen.</p></div></article><article><span>10</span><div><b>Team-Time-out</b><p>Patient, Ziel, Aufgaben, Kommunikationsweg, erwartbare Komplikationen und Rückfallebene gemeinsam bestätigen.</p></div></article></div><aside className="communication-exam-tip"><b>Prüfungsfalle</b><p>„Transportfähig“ bedeutet nicht beschwerdefrei oder risikolos. Es bedeutet, dass die notwendige Therapie, Überwachung und Beherrschung vorhersehbarer Komplikationen während des gesamten Transports gewährleistet sind.</p></aside></div></DiagnostikSection>
      <DiagnostikSection number="25" kicker="Neurologie" title="Todd’sche Parese nach einem Krampfanfall"><div className="communication-copy"><aside className="communication-case"><small>Definition</small><p>Die Todd’sche Parese ist ein vorübergehendes fokales neurologisches Defizit nach einem epileptischen Anfall, meist eine einseitige Schwäche. Auch Sprach-, Seh- oder Sensibilitätsstörungen können postiktal auftreten.</p></aside><div className="communication-compare"><article><small>Spricht dafür</small><h3>Zeitlicher Zusammenhang</h3><p>Das Defizit folgt unmittelbar auf einen beobachteten Anfall und bildet sich im Verlauf typischerweise zurück. Dauer und Befund werden seriell dokumentiert.</p></article><article><small>Gefährliche Alternative</small><h3>Schlaganfall oder Blutung</h3><p>Ein Anfall kann durch einen Schlaganfall ausgelöst werden. Eine neue fokale Störung wird deshalb präklinisch nicht einfach als Todd-Parese abgetan.</p></article></div><aside className="communication-exam-tip"><b>Konsequenz</b><p>BE-FAST beziehungsweise neurologischen Status, BZ, Zeitpunkt von Anfall und Defizit sowie Verlauf erfassen. Bei neuem oder anhaltendem fokalem Ausfall den Schlaganfallpfad und eine geeignete Zielklinik berücksichtigen.</p></aside></div></DiagnostikSection>
      <DiagnostikSection number="26" kicker="Pädiatrie" title="Kinder beurteilen und invasive Maßnahmen sicher vorbereiten"><div className="communication-copy"><p>Bei Kindern sind Vitalwerte, Atemzugvolumen und Reserven stark altersabhängig. Entscheidend sind deshalb <b>Gesamteindruck, Atemarbeit, Hautdurchblutung, Vigilanz und Verlauf</b> – nicht ein isolierter Tabellenwert.</p><aside className="communication-case"><small>Pädiatrische Reanimation</small><p><b>Fünf Initialbeatmungen sofort:</b> Sie dürfen nicht verzögert werden, nur weil Sauerstoff noch nicht angeschlossen ist. Ist Sauerstoff verfügbar, wird im professionellen Reanimationssetting mit Beutel-Maske und möglichst hoher inspiratorischer Sauerstoffkonzentration beatmet. Ein pauschaler Flow von 6–8 l/min ist kein allgemeiner Reanimationszielwert; Flow und Reservoirfüllung richten sich nach System, Geräteeinweisung und Algorithmus.</p></aside><h3>Altersbezogene Lernorientierung der Schulunterlage</h3><div className="table-scroll diagnostik-table paediatric-vitals-table"><table><thead><tr><th scope="col">Gruppe</th><th scope="col">Alter</th><th scope="col">Gewicht</th><th scope="col">AF/min</th><th scope="col">AZV</th><th scope="col">HF/min</th></tr></thead><tbody><tr><th scope="row">Neugeborenes</th><td>1–28 Tage</td><td>2–4 kg</td><td>40</td><td>20–40 ml</td><td>140–160</td></tr><tr><th scope="row">Säugling</th><td>28 Tage–12 Monate</td><td>5–10 kg</td><td>30</td><td>40–100 ml</td><td>120–140</td></tr><tr><th scope="row">Kleinkind</th><td>12 Monate–5 Jahre</td><td>11–30 kg</td><td>25</td><td>100–200 ml</td><td>100–120</td></tr><tr><th scope="row">Schulkind</th><td>5–13 Jahre</td><td>30–60 kg</td><td>20</td><td>200–400 ml</td><td>80–100</td></tr><tr><th scope="row">Jugendlicher</th><td>13–18 Jahre</td><td>&gt;60 kg</td><td>15</td><td>300–500 ml</td><td>60–80</td></tr></tbody></table></div><aside className="communication-exam-tip"><b>So lernst du die Tabelle richtig</b><p>AF = Atemfrequenz, AZV = ungefähres absolutes Atemzugvolumen, HF = Herzfrequenz. Die Werte sind <b>Lernorientierungen der Schule</b>, keine starren Diagnosegrenzen. Messqualität, Alter, Gewicht, Fieber, Schmerz, Aufregung und Verlauf werden mitbewertet.</p></aside><aside className="red-flags"><span>!</span><div><small>Spätes Warnzeichen</small><h3>Bradykardie beim akut kranken Kind ist kritisch</h3><p>Das kindliche Herzzeitvolumen hängt stark von der Herzfrequenz ab. Eine neu auftretende oder relative Bradykardie bei Hypoxie, Schock oder Vigilanzabfall spricht für fortgeschrittene Dekompensation: sofort cABCDE, Oxygenierung und Ventilation prüfen und nach dem gültigen pädiatrischen Algorithmus handeln. Eine isoliert niedrige Herzfrequenz ohne passenden klinischen Kontext bedeutet dagegen nicht automatisch Kreislaufstillstand.</p></div></aside><div className="communication-grid"><article><b>Atemweg &amp; Atmung</b><p>Großer Hinterkopf, relativ große Zunge, kleine Atemwege und geringere Sauerstoffreserve begünstigen rasche Verlegung und Desaturation. Säuglinge neutral lagern statt den Kopf maximal zu überstrecken; Atemarbeit an Nasenflügeln, Einziehungen und Erschöpfung erkennen.</p></article><article><b>Kreislauf</b><p>Kinder kompensieren lange über Tachykardie und Vasokonstriktion. Hypotonie ist häufig spät. Haut, Rekapillarisierung, periphere Pulse, Vigilanz und Trend gehören zur Beurteilung.</p></article><article><b>Wärmeerhalt</b><p>Große Körperoberfläche, wenig Unterhautfett und geringe Kältezitterreserve fördern Wärmeverlust. Entkleidung nur gezielt und kurz, anschließend konsequent wärmen.</p></article><article><b>Krampfanfall</b><p>Beginn, Dauer, fokale Zeichen, Erholung, Fieber, Trauma, mögliche Intoxikation, familiär erreichbare Medikamente und bereits gegebene Notfallmedikation erfragen. Ein laufender konvulsiver Anfall ab fünf Minuten ist zeitkritisch.</p></article><article><b>Zugang &amp; Applikation</b><p>Bei vitaler Bedrohung und nicht rasch möglichem i.v.-Zugang früh an den intraossären Weg denken. Intranasale, intramuskuläre und rektale Wege richten sich nach Indikation, VFA und geeignetem Material.</p></article><article><b>Schmerz</b><p>Altersgerechte Skala wählen: Beobachtungsskala bei Säuglingen/Kleinkindern, Gesichterskala ab etwa drei Jahren, NRS häufig ab Schulalter; Bezugspersonen und Verlauf einbeziehen.</p></article></div><h3>Trauma-Besonderheiten</h3><div className="communication-compare"><article><small>Verletzungsmuster</small><h3>Hohe Knochenelastizität</h3><p>Schwere Thorax- oder Abdominalverletzungen sind trotz fehlender Fraktur möglich. Umgekehrt kann eine Fraktur beim Kind auf relevante Energieeinwirkung hinweisen.</p></article><article><small>Skelettentwicklung</small><h3>Offene Wachstumsfugen</h3><p>Verletzungen können die weitere Knochenentwicklung beeinträchtigen. Schonende Untersuchung, pDMS, passende Immobilisation und Verlaufskontrolle sind wichtig.</p></article></div><h3>Geeignete Gefäßzugänge</h3><div className="material-chips"><span>Handrücken</span><span>Unterarminnenseite / Ellenbeuge</span><span>Fußrücken</span><span>Innenknöchel</span><span>Kopfhautvene · Pulsation beachten</span><span>V. jugularis externa · technisch oft schwierig</span><span>i.o. bei vitaler Bedrohung nach VFA</span></div><p>Bei Kopfhautgefäßen Arterie und Vene sorgfältig unterscheiden. Ein belastender i.v.-Versuch darf zeitkritische Versorgung nicht verzögern; Indikation und Punktionsort des intraossären Zugangs richten sich nach Kinder-VFA, System und Einweisung.</p><h3>Medikamente beim Kind sicher vorbereiten</h3><div className="qm-learning-chain"><span><b>1</b>Gewicht messen, erfragen oder valide schätzen</span><i>→</i><span><b>2</b>Kinder-VFA und kognitive Hilfe nutzen</span><i>→</i><span><b>3</b>Vier-Augen-Kontrolle</span><i>→</i><span><b>4</b>kleine Spritze wählen und beschriften</span><i>→</i><span><b>5</b>Wirkung und Nebenwirkung reevaluieren</span></div><p>Medikamente möglichst unmittelbar vor der Anwendung vorbereiten, unnötige Verdünnungen vermeiden und bereits durch Bezugspersonen oder andere Helfer verabreichte Dosen ausdrücklich mitrechnen. Kurze Leitungswege, patientennaher Anschluss und notwendiges Nachspülen vermindern Dosierungsverluste.</p></div></DiagnostikSection>
      <DiagnostikSection number="27" kicker="Neugeborenenversorgung" title="APGAR-Score und sichere Medikamentenanamnese"><div className="communication-copy"><p>Der <b>APGAR-Score</b> beschreibt die Anpassung des Neugeborenen nach der Geburt. Jeder der fünf Bereiche erhält <b>0, 1 oder 2 Punkte</b>. Regulär wird nach <b>1 und 5 Minuten</b> dokumentiert; liegt der Wert unter 7, wird in Fünf-Minuten-Abständen bis 20 Minuten weiter bewertet. In deutschen Prüfungsschemata wird häufig zusätzlich der Wert nach 10 Minuten genannt.</p><div className="table-scroll diagnostik-table"><table><thead><tr><th scope="col">Merkmal</th><th scope="col">0 Punkte</th><th scope="col">1 Punkt</th><th scope="col">2 Punkte</th></tr></thead><tbody><tr><th scope="row">A · Aussehen / Hautfarbe</th><td>blass oder zentral zyanotisch</td><td>Stamm rosig, Akrozyanose</td><td>vollständig rosig</td></tr><tr><th scope="row">P · Puls / Herzfrequenz</th><td>nicht vorhanden</td><td>unter 100/min</td><td>mindestens 100/min</td></tr><tr><th scope="row">G · Grundtonus / Muskeltonus</th><td>schlaff</td><td>leichte Beugung</td><td>aktive Bewegung</td></tr><tr><th scope="row">A · Atmung</th><td>keine</td><td>langsam, unregelmäßig oder schwacher Schrei</td><td>regelmäßig, kräftiger Schrei</td></tr><tr><th scope="row">R · Reflexe</th><td>keine Reaktion</td><td>Grimassieren</td><td>Husten, Niesen, Schreien oder aktives Zurückziehen</td></tr></tbody></table></div><div className="communication-compare"><article><small>Lernorientierung</small><h3>Gesamtwert 0–10</h3><p><b>8–10:</b> gute Anpassung. <b>5–7:</b> Anpassung beeinträchtigt. <b>0–4:</b> schwer beeinträchtigt. Einzelbefunde, Verlauf und laufende Maßnahmen sind wichtiger als die Summe allein.</p></article><article><small>Prüfungsfalle</small><h3>Nicht auf den Score warten</h3><p>Der APGAR-Score ist kein Startsignal für die Reanimation. Akute Entscheidungen richten sich sofort nach Atmung, Herzfrequenz, Muskeltonus und klinischem Zustand. Notwendige Beatmung oder Reanimation darf nicht verzögert werden.</p></article></div><aside className="communication-case"><small>Rechenbeispiel</small><p>Stamm rosig bei blauen Händen und Füßen = 1, Herzfrequenz 120/min = 2, leichte Beugung = 1, unregelmäßige Atmung = 1 und Grimassieren auf Reiz = 1. <b>APGAR: 6 Punkte.</b></p></aside><h3>Vor jeder Medikamentengabe beim Kind</h3><div className="legal-checklist"><span>Allergien und bekannte Unverträglichkeiten erfragen</span><span>bereits gegebene Medikamente mit Wirkstoff, Dosis, Weg und Uhrzeit erfassen</span><span>Gewicht und verwendete Konzentration prüfen</span><span>Doppelgaben ausdrücklich ausschließen</span><span>Wirkung und Nebenwirkung erneut beurteilen</span></div><p>Eltern, Betreuungspersonen, Ersthelfende und bereits beteiligte Einsatzkräfte werden gezielt gefragt. Handelsnamen allein reichen nicht: Entscheidend sind Wirkstoff, Menge, Konzentration, Applikationsweg und Zeitpunkt.</p></div></DiagnostikSection>
    </div>
    {finale}
    <section className="legal-sources communication-sources"><span className="eyebrow">Fachliche Grundlage</span><h2>Abgleich und Grenzen</h2><p>Abgeglichen mit den Thüringer VFA 02 zum intraossären Zugang und 07 zur Entlastungspunktion, den bereitgestellten Lehrunterlagen zu Pulsoxymetrie, Kapnometrie/Kapnografie und pädiatrischen invasiven Maßnahmen (Schulunterlage 2026), den NEXUS-Low-Risk-Kriterien, diabetologischen Orientierungswerten, den Empfehlungen von BGW, DGUV und RKI zu Nadelstichverletzung und Postexpositionsprophylaxe, den ERC-Leitlinien 2025, der AWMF-S3-Leitlinie Polytrauma/Schwerverletzten-Behandlung, den DIVI-Empfehlungen und dem DIVI-Curriculum zum Intensivtransport, der DGAI-Handlungsempfehlung zur präklinischen Notfallnarkose, den Herstellerangaben des Arrow EZ-IO-Systems sowie dem DFG-Kodex zur guten wissenschaftlichen Praxis. Lokale VFA, Hygieneplan, Geräteeinweisung, ÄLRD-Vorgaben und individuelle Kompetenzgrenzen bleiben maßgeblich.</p></section>
  </section>;
}
